import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"Replication reads the change log after the tick","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Replication reads the change log after the tick"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/adr/0016-replication-reads-the-change-log"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/adr/0016-replication-reads-the-change-log"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/adr/0016-replication-reads-the-change-log.md"}},"headers":[],"relativePath":"adr/0016-replication-reads-the-change-log.md","filePath":"adr/0016-replication-reads-the-change-log.md","lastUpdated":1794437834000}`),a={name:`adr/0016-replication-reads-the-change-log.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="replication-reads-the-change-log-after-the-tick" tabindex="-1">Replication reads the change log after the tick <a class="header-anchor" href="#replication-reads-the-change-log-after-the-tick" aria-label="Permalink to “Replication reads the change log after the tick”">​</a></h1><p>Status: accepted</p><p>Replication is a read-only stage that runs after a tick closes. It reads the tick&#39;s change log (<a href="/pr-preview/pr-2948/adr/0012-the-change-log-is-the-history.html">ADR 0012</a>) and nothing else from the simulation. It computes the audience for each change once per tick, encodes once for each protocol codec and compression group, and sends. It never compares current state with the values it last sent. Handlers and other simulation code stop sending packets per viewer. An occurrence such as an animation or a hurt effect is a log entry, and replication turns it into packets.</p><p>A player who walks into range of an entity that has not changed needs that entity&#39;s full state, and no entry of the current tick carries it. Replication therefore keeps a replica: the fields clients are sent for each entity, folded from the log. A membership entry carries the entity&#39;s full replicated state, so the replica starts complete and every later entry updates it. A first sight is answered from the replica, and the spawn packet is encoded once for each codec group, not once for each viewer. The replica holds only what the log already delivered, so replication still reads nothing else from the simulation, and it is the plain data a worker would need.</p><p>Today health crosses between a mob&#39;s two models by comparing the body&#39;s value with the last one the mirror wrote. Handlers such as <code>AnimateHandler</code> encode and compress once per viewer, although the replicator already has an encode-once path. Replication also reads entity objects directly. Reading a plain-data log removes the comparison, the per-viewer encoding and the dependency on entity objects, and it lets the stage move to another thread later (<a href="/pr-preview/pr-2948/adr/0011-a-world-exchanges-only-plain-data.html">ADR 0011</a>).</p><p>The test is a count. The number of encode calls for one broadcast occurrence equals the number of codec and compression groups, whatever the number of viewers.</p></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};